export const inspiracaoVariants = (variants) => INSPIRACAO_BASES.map(({ id, from, title, set }) => {
  const origin = variants.find((variant) => variant.id === from);
  return { ...origin, id, title, ...(set ?? {}) };
});

export const INSPIRACAO_T = {
  pt: {
    "V2-252": ["Pôr do sol para dois, sem tela e com uma gratidão","Ver o céu mudar de cor lado a lado acalma o ritmo e abre espaço para dizer 'obrigado' sem pressa.",["Vejam a hora do pôr do sol e cheguem 15 minutos antes a um lugar aberto, como uma praça, um muro ou um mirante.","Deixem o celular no bolso e sentem-se perto.","Enquanto o sol desce, cada um diz em voz baixa uma coisa que agradece no outro esta semana.","Fiquem em silêncio até a luz acabar, de mãos dadas.","Voltem andando devagar, sem falar de tarefas."],"Levem um casaco: o fim da tarde esfria rápido.",null,null],
    "V2-253": ["Passeio até o lugar onde tudo começou","Voltar ao lugar do começo lembra por que vocês se escolheram e traz de volta a leveza do início.",["Escolham um lugar da história de vocês: onde se viram pela primeira vez, onde se beijaram ou onde conversaram a noite toda.","Vão a pé, contando no caminho o que cada um lembra daquele dia.","Quando chegarem, parem 5 minutos e digam o que sentiram naquela época.","Depois, cada um diz o que ama no outro hoje e que não existia lá atrás.","Tirem uma foto juntos, no mesmo ângulo de antes, se tiverem a antiga."],"Se o lugar mudou ou fechou, fiquem do lado de fora: a lembrança vale igual.",null,null],
    "V2-254": ["Banco de jardim e uma carta lida em voz alta","Escrever e ler em voz alta diz mais do que a conversa corrida, e o jardim deixa tudo mais calmo.",["Escrevam, cada um em casa, uma carta curta para o outro, com 3 coisas que valorizam.","Levem as cartas e escolham um banco calmo num jardim ou parque.","Sentem-se lado a lado e leiam, um de cada vez, sem interromper.","Depois de cada carta, o outro só responde 'obrigado' e um abraço.","Guardem as cartas para reler no próximo mês."],"Se der vergonha ler, troquem as cartas e leiam em silêncio, de mãos dadas.",null,null],
    "V2-255": ["Volta pelo bairro agradecendo o que já temos","Reparar no que já é bom na vida de vocês, uma rua de cada vez, reaproxima mais do que desejar o que falta.",["Saiam para uma volta de uma hora pelo bairro, sem destino.","A cada esquina, um aponta algo que agradece: a padaria, a árvore, o vizinho simpático.","Na esquina seguinte, é a vez do outro.","Na metade da volta, parem e digam um agradecimento só para o outro.","Terminem em casa com um abraço longo."],"Se virarem queixa, voltem ao jogo: só vale agradecer.",null,null],
    "V2-256": ["Tarde de jardim público para falar do futuro","Falar de sonhos andando entre plantas e sombra deixa o assunto leve e faz cada um se sentir ouvido.",["Escolham um jardim público e cheguem sem pressa, com água e um lanche simples.","Andem uns 30 minutos em silêncio, só olhando e aproveitando.","Sentem-se e cada um conta um sonho para daqui a cinco anos, sem julgamento.","Escolham juntos um pequeno passo que dê para começar este mês.","Escrevam o passo num papel e levem para casa."],"Qualquer um pode pedir um tempo de silêncio quando quiser.",null,null],
    "V2-257": ["Tarde de mirante e carta para daqui a um ano","De cima, a cidade parece pequena e os problemas também, e é um bom lugar para escrever para o futuro.",["Escolham um mirante ou lugar alto e sigam a pé ou de transporte público.","Cada um leva papel e caneta.","No alto, olhem a paisagem por 10 minutos sem falar.","Escrevam uma carta para o casal daqui a um ano, com desejos e promessas simples.","Dobrem as cartas e combinem a data para abri-las."],"Marquem no calendário o dia de abrir as cartas, para não esquecerem.",null,null],
    "V2-258": ["Hora de observar pessoas e inventar histórias num banco","Inventar a vida de quem passa faz rir e mostra como cada um enxerga o mundo, de graça e sem preparo.",["Escolham um banco com boa vista de gente passando, como numa praça ou numa avenida.","Cada um escolhe uma pessoa de longe e inventa seu nome, sua profissão e seu dia.","Revezem os personagens por uma hora, sem apontar nem encarar ninguém.","Votem na história mais divertida e na mais romântica.","Na volta, inventem a história de vocês dois, como se outros contassem."],"Respeitem as pessoas: nada de ofensas, só histórias carinhosas.",null,null],
    "V2-259": ["Hora de patos e pássaros no parque, em silêncio","Olhar bichos com calma desacelera e obriga a ficar no presente, lado a lado.",["Escolham um lago, jardim ou parque com patos e pássaros.","Não levem pão nem restos de comida: bicho não se alimenta, só se observa.","Sentem-se em silêncio por 15 minutos e contem quantas espécies viram.","Cada um escolhe o bicho favorito do dia e explica por quê.","Terminem com uma volta devagar ao redor da água."],"Quanto mais quietos, mais bichos aparecem: levem paciência.",null,null],
    "V2-260": ["Caça de cores pelo bairro, com fotos","Procurar uma cor por vez muda o olhar sobre ruas que vocês já conhecem e vira uma pequena competição leve.",["Combinem 5 cores: vermelho, azul, amarelo, verde e uma surpresa.","Saiam a pé por uma hora e fotografem uma coisa de cada cor.","Quem achar primeiro marca ponto, mas vale a foto mais bonita.","Sentem-se e mostrem as fotos, contando por que escolheram cada uma.","Escolham juntos a melhor foto do dia."],"Deixem as fotos num álbum só de vocês dois.",null,null],
    "V2-261": ["Duas ruas que nunca percorremos","Trocar o caminho de sempre por duas ruas novas dá a sensação de pequena viagem sem sair do bairro.",["Cada um escolhe uma rua que nunca percorreu, perto de casa.","Caminhem pela primeira e vão contando o que notam de diferente.","Depois sigam pela segunda e comparem as duas.","Votem na rua mais bonita e na mais curiosa.","Anotem a favorita para voltar noutro dia."],"Levem água e um casaco leve: o passeio pode render mais do que o previsto.",null,null],
    "V2-262": ["Piquenique da hora azul ao entardecer","A luz do fim do dia deixa tudo mais bonito, e um piquenique simples vira cena de filme sem gastar quase nada.",["Quem organiza prepara uma pequena cesta com coisas simples que já tem em casa.","O outro só sabe a hora e o ponto de encontro.","No lugar, estendam uma toalha e sentem-se de frente para o céu.","Comam devagar vendo a luz mudar do dourado ao azul.","Terminem com uma frase de cada um sobre o que mais gostou do dia."],"Levem uma luz pequena para a volta, se escurecer.",null,"Quem organiza escolhe o lugar e a cesta em segredo; o outro só descobre ao chegar."],
    "V2-263": ["Mini caça fotográfica com três desafios secretos","Desafios curtos tornam uma volta comum em jogo, e as fotos viram lembrança sem custo.",["Quem organiza escreve 3 desafios em papéis fechados, como 'algo redondo', 'algo que te faz sorrir' e 'algo que lembra a gente'.","Saiam para uma caminhada de uma hora.","Abram um desafio por vez e fotografem a resposta.","Ao final, mostrem as fotos e expliquem as escolhas.","Votem na mais criativa."],"Escolham desafios fáceis, para a graça vir da escolha e não da dificuldade.",null,"Quem organiza esconde os desafios; o outro só os descobre ao abrir cada papel."],
    "V2-264": ["Passeio em que o outro escolhe cada curva","Entregar o rumo ao outro é um pequeno ato de confiança, e o caminho vira surpresa para os dois.",["Combinem uma hora de passeio e um ponto de partida.","A cada esquina, quem lidera diz esquerda, direita ou reto.","Quem segue não pergunta para onde vão.","Na metade, troquem: agora o outro escolhe as curvas.","Terminem num banco e contem o que acharam de mais bonito."],"Combinem de antemão que sem perigo e sem ruas escuras.",null,"Quem lidera escolhe as curvas na hora; o outro só acompanha."],
    "V2-265": ["Dia do nascer ao pôr do sol: um bilhete para cada hora","Um dia inteiro com um bilhete por hora faz a surpresa durar e transforma cada hora numa pequena cena.",["Quem organiza escreve 8 bilhetes, um para cada hora do dia, com um lugar ou uma ação simples.","De manhã, vejam o sol nascer ou tomem café na rua.","Abram um bilhete por hora e cumpram com calma.","Alternem passeios, pausas e conversas.","Ao pôr do sol, entreguem o último bilhete: uma frase de amor."],"Deixem uma hora livre no meio, para o dia respirar.",null,"Quem organiza prepara os bilhetes; o outro só abre um a cada hora."],
    "V2-266": ["Dia de mapa do tesouro: pistas pela cidade","Seguir pistas por lugares conhecidos faz a cidade parecer nova e rende um dia de aventura leve.",["Quem organiza desenha um mapa simples com 5 paradas, cada uma com uma pista.","Cada parada é um lugar de graça, como uma praça, um mirante ou um jardim.","Na primeira parada, abram a primeira pista.","Em cada local, façam o que a pista pedir: contar uma lembrança, tirar uma foto, dar um elogio.","No fim, o tesouro é um piquenique ou um abraço combinado."],"Guardem o mapa: ele vira lembrança.",null,"Quem organiza escolhe as paradas e as pistas; o outro só segue."],
    "V2-267": ["Dia de piquenique-mistério com três paradas","Um piquenique espalhado em três paradas dá ritmo ao dia e deixa a surpresa crescer.",["Quem organiza esconde três momentos: aperitivo, prato principal e sobremesa, cada um num lugar.","Os dois caminham entre os lugares, conversando.","Em cada parada, abram um bilhete que diz o que fazer.","Comam devagar e aproveitem o lugar.","Voltem para casa sem pressa, de mãos dadas."],"Levem toalha e um saco para o lixo: deixem tudo limpo.",null,"Quem organiza escolhe as paradas e o cardápio; o outro só descobre uma por vez."],
    "V2-268": ["Dia de cafés e livros: um bilhete em cada parada","Passar um dia entre cafés calmos e estantes de livros, com bilhetes escondidos, mistura aconchego e surpresa.",["Quem organiza escolhe 4 lugares de que vocês gostam, como um café, uma biblioteca e uma livraria.","Escreve um bilhete para cada parada, com um elogio, uma pergunta ou uma tarefa.","Em cada lugar, abram o bilhete e leiam em voz alta.","Escolham um livro ou uma página para ler juntos baixinho.","Terminem o dia com um bilhete de despedida."],"Em livrarias e cafés, só leiam e peçam o que for do gosto de vocês; sem pressão para comprar.",null,"Quem organiza escreve os bilhetes; o outro só abre um por parada."],
    "V2-269": ["Dia de lojas e feiras só para olhar, com missões secretas","Passear por feiras e lojas sem comprar vira jogo, e as missões deixam o dia leve e curioso.",["Quem organiza prepara 5 missões, como 'encontre algo que combine com o outro' ou 'ache o objeto mais antigo'.","Vão a feiras e lojas de segunda mão, só para olhar.","Abram uma missão por parada e cumpram juntos.","Registrem as respostas em fotos, sem comprar nada.","Ao final, escolham o achado favorito e riam das escolhas."],"Se um dos dois quiser levar algo, vale: a regra é só não precisar.",null,"Quem organiza escreve as missões; o outro só descobre uma de cada vez."],
    "V2-270": ["Dia de museus e jardins gratuitos, com sorteio de roteiro","Deixar o acaso decidir o roteiro tira a pressão de escolher e dá ao dia um toque de aventura.",["Quem organiza lista 6 lugares gratuitos ou de entrada livre na cidade.","Escrevam os nomes em papéis dobrados.","A cada parada, sorteiem o próximo lugar.","Em cada lugar, escolham juntos uma coisa para olhar com calma e conversar sobre ela.","Terminem o dia no lugar sorteado por último, com um lanche."],"Confiram os horários antes de sair, para não darem com a porta fechada.",null,"Quem organiza lista os lugares; o sorteio decide o resto na hora."],
    "V2-271": ["Turistas no próprio bairro: uma hora com guia inventado","Olhar o bairro como visitante revela detalhes que o dia a dia esconde, e a brincadeira de guia deixa tudo mais leve.",["Escolham quem é o guia e quem é o turista, e combinem uma hora de passeio.","O guia mostra o bairro como se fosse um ponto turístico, inventando histórias.","O turista faz perguntas curiosas e tira fotos.","Na metade, troquem os papéis.","Terminem num banco, avaliando o passeio com nota de 0 a 10."],"Nada de gastar: o prêmio é a risada.",null,null],
    "V2-272": ["Hora de mural e arte de rua: cada um escolhe o preferido","Procurar arte nas paredes da cidade treina o olhar e mostra o gosto de cada um sem precisar de explicação.",["Escolham uma rua ou bairro com murais e arte de rua.","Andem devagar, olhando as paredes.","Cada um escolhe seu preferido e explica o que sente ao ver.","Fotografem os dois escolhidos, lado a lado.","Votem no mais bonito e no mais estranho."],"Respeitem os moradores: observem sem tocar, sem atrapalhar.",null,null],
    "V2-273": ["Leitura em voz alta numa livraria: um trecho para o outro","Ler um trecho para quem a gente ama é um carinho barato e muito íntimo, e a livraria dá o clima perfeito.",["Cada um escolhe um livro na prateleira, sem comprar.","Procure um trecho bonito ou engraçado, de uma ou duas páginas.","Num canto tranquilo, leiam em voz baixa, um para o outro.","Depois de cada leitura, contem por que escolheram aquele trecho.","Saiam juntos, comentando qual foi o favorito."],"Leiam baixinho, para não incomodar quem está por perto.",null,null],
    "V2-274": ["Visita a um lugar da nossa história e uma frase de agradecimento","Voltar a um lugar importante e dizer 'obrigado' ali cola a lembrança ao carinho de hoje.",["Escolham um lugar que marcou vocês, como o primeiro café ou a primeira rua em que caminharam juntos.","Vão sem pressa, lembrando do caminho.","No lugar, cada um diz uma frase de agradecimento ao outro, olhando nos olhos.","Contem o que o lugar significa hoje para vocês.","Combinem de voltar ali num dia especial."],"Uma foto sem pose, de mãos dadas, fecha bem o momento.",null,null],
    "V2-275": ["Hora na biblioteca: escolher um livro para ler a dois","Escolher juntos um livro para ler é um pequeno plano de futuro, de graça, e dá assunto para muitas noites.",["Vão à biblioteca e passeiem pelas estantes sem pressa.","Cada um apresenta ao outro um livro de que gosta, em um minuto.","Escolham um só para ler os dois, em capítulos.","Se puderem emprestar, combinem o dia de leitura da semana.","Terminem sentados, lendo juntos a primeira página."],"Se a biblioteca não tiver o livro, anotem o título e procurem outra.",null,null],
    "V2-276": ["Calendário a dois: marcar três encontros futuros num banco","Planejar os próximos encontros juntos dá algo para esperar e mostra que os dois querem continuar.",["Escolham um banco, um café ou um jardim tranquilo.","Levem a agenda ou o calendário do celular.","Cada um propõe uma ideia de encontro, de graça ou barata.","Marquem três datas para as próximas semanas e escrevam no calendário.","Brindem com água, café ou chá ao combinado."],"Escolham datas realistas: pequenas e certas valem mais que grandes e incertas.",null,null],
    "V2-277": ["Tarde de teatrinho em casa: um número secreto de cada um","Preparar um número secreto para o outro mistura nervoso, riso e carinho numa tarde só de vocês.",["Combinem em segredo: cada um prepara um número de 3 a 5 minutos, como uma mímica, uma música ou uma história.","Separem-se por uma hora para ensaiar, cada um num cômodo.","Montem um palco simples na sala, com cortina de lençol.","Apresentem, um de cada vez, com direito a aplauso.","Votem no número mais engraçado e no mais emocionante."],"Quem errar mais ganha o prêmio de 'mais corajoso'.",null,"Cada um prepara o número em segredo; só se descobre na hora de apresentar."],
    "V2-278": ["Tarde de cartas escondidas pela casa: uma por hora","Cartas que aparecem uma por vez fazem a tarde render carinho em pequenas doses.",["Quem organiza escreve 4 cartas curtas, cada uma com um elogio, uma lembrança ou uma tarefa leve.","Esconde as cartas em lugares da casa, antes de o outro chegar.","A cada hora, o outro procura uma carta, com uma dica.","Cada carta é lida em voz alta e respondida com um gesto.","Na última, o recado é: 'venha me encontrar'."],"Escolham esconderijos seguros, sem atrapalhar ninguém da casa.",null,"Quem organiza esconde as cartas; o outro só procura uma por hora."],
    "V2-279": ["Tarde de degustação às cegas com o que há na despensa","Provar com os olhos fechados muda o gosto e faz rir, e usa só o que vocês já têm em casa.",["Quem organiza separa 6 itens da despensa, como uma fruta, um queijo, um pão, um chocolate, um tempero e um doce.","O outro senta com os olhos vendados.","Dê cada item em pequenas porções, e o outro tenta adivinhar.","Troquem os papéis.","Contem quem acertou mais e comam os preferidos juntos."],"Confiram antes alergias e preferências, e nada de itens que o outro não goste.",null,"Quem organiza escolhe os itens em segredo; o outro só prova e adivinha."],
    "V2-280": ["Bilhete escondido num banco de jardim","Um bilhete esperando em lugar combinado faz o passeio curto virar presente.",["Quem organiza escreve um bilhete carinhoso e esconde num banco, ou o leva no bolso.","Convida o outro para uma hora de passeio num jardim ou parque.","Passeiem e, quando chegarem ao banco, peça ao outro que procure.","O outro lê o bilhete em voz alta, e responde com um abraço.","Fiquem um tempo sentados, em silêncio."],"Se escondem o bilhete, usem um lugar que não prejudique ninguém, e recolham o papel depois.",null,"Quem organiza esconde o bilhete; o outro só o descobre no banco."],
    "V2-281": ["Procurar o lugar mais bonito do bairro, escolhido em segredo","Escolher um recanto bonito para o outro mostra o quanto a gente observa quem ama.",["Cada um escolhe, em segredo, um recanto do bairro que acha bonito.","Combinem uma hora de passeio.","Cada um leva o outro até o seu lugar, sem dizer onde é.","Em cada lugar, contem por que o escolheram.","Fotografem os dois recantos e escolham o mais especial."],"Podem usar lugares simples: um banco, uma janela, uma árvore.",null,"Cada um escolhe o seu recanto em segredo; o outro só descobre ao chegar."],
    "V2-282": ["Livro surpresa: um escolhe a página, o outro lê em voz alta","Ler uma página escolhida pelo outro é uma surpresa pequena, íntima e de graça.",["Vão a uma biblioteca ou a uma estante de livros de casa.","Quem organiza escolhe em segredo um livro e uma página bonita.","O outro lê a página em voz alta, sem ter visto antes.","Conversem sobre o que acharam e o que sentiram.","Troquem os papéis."],"Escolham textos curtos e gentis: a leitura fica mais leve.",null,"Quem organiza escolhe o livro e a página em segredo; o outro só lê na hora."],
    "V2-283": ["Tarde de pôr do sol, banco e termo de chá","Um chá quente, um banco e o céu mudando fazem a tarde render conversa boa e devagar.",["Preparem um termo de chá ou café e levem dois copos.","Escolham um banco ou muro com vista aberta.","Cheguem antes do pôr do sol e sentem-se de frente para o céu.","Conversem sobre o dia, sem pressa e sem tela.","Quando escurecer, voltem andando de braços dados."],"Levem uma mantinha pequena: o banco esfria depressa.",null,null],
    "V2-284": ["Tarde de bicicleta sem pressa até um mirante","Pedalar devagar lado a lado dá tempo de conversar e de olhar a cidade de outro ângulo.",["Escolham um trajeto tranquilo, de preferência por ciclovia ou rua calma.","Levem água e um lanche simples.","Pedalem em ritmo de conversa, sem competir.","Parem num mirante ou jardim e descansem um pouco.","Voltem com calma, sem pressa e com atenção ao trânsito."],"Se um dos dois não tiver bicicleta, podem fazer o mesmo trajeto a pé.",null,null],
    "V2-285": ["Tarde no jardim sem pressa: nomear flores e árvores","Dar nome ao que a gente vê, mesmo inventado, faz olhar com carinho e rir juntos.",["Escolham um jardim ou parque com bastante verde.","Levem um caderno pequeno e uma caneta.","Cada um dá um nome inventado a uma flor ou árvore e explica a escolha.","Anotem os nomes e desenhem rápido, sem se preocupar com talento.","Terminem no banco mais bonito, lendo a lista em voz alta."],"Respeitem as plantas: olhar e desenhar, sem colher.",null,null],
    "V2-286": ["Tarde de música de rua e concertos livres","Ouvir música ao vivo, sem pressa e sem bilhete, deixa a tarde mais bonita e dá assunto de graça.",["Procurem uma praça, um jardim ou uma rua onde costuma ter música ao vivo, ou um concerto livre.","Cheguem sem expectativa e escutem de pé ou sentados.","Cada um escolhe a música que mais gostou e conta por quê.","Se tiverem vontade, dancem um pouco de mãos dadas.","Terminem com uma volta, cantarolando a favorita."],"Se tiverem moeda, podem deixar um gesto de carinho ao artista, mas sem obrigação.",null,null],
    "V2-287": ["Passeio pelas casas dos sonhos: olhar de fora e imaginar","Imaginar onde moram os sonhos do casal é uma forma divertida de falar de futuro sem compromisso.",["Escolham um bairro bonito com casas ou prédios que gostam de olhar.","Passeiem devagar, olhando as fachadas.","Cada um escolhe a casa dos sonhos e explica por quê.","Imaginem juntos como seria a vida lá: cozinha, jardim, varanda.","Fotografem as favoritas e escolham uma para o 'sonho do casal'."],"Respeitem a privacidade de quem mora: olhar sem se aproximar das janelas.",null,null],
    "V2-288": ["Tarde de abrigo de animais: voluntariado de passeio e carinho","Cuidar de bichos que esperam um lar aproxima o casal e deixa uma tarde com sentido.",["Procurem um abrigo de animais da região e combinem a visita antes, perguntando se aceitam voluntários.","Cheguem no horário combinado e sigam as regras do local.","Ajudem com o que for pedido, como passear com cães ou dar carinho a gatos.","Conversem sobre a experiência no caminho de volta.","Combinem de voltar numa outra tarde."],"Só adotem se os dois estiverem prontos e tiverem conversado com calma antes.",null,null],
    "V2-289": ["Dia de cápsulas surpresa: uma atividade escondida por hora","Um dia em casa com uma atividade secreta por hora nunca fica parado e mantém a curiosidade acesa.",["Quem organiza escreve 6 atividades em papéis dobrados, usando só o que há em casa, como dançar, cozinhar algo simples ou ler em voz alta.","Coloca os papéis numa caixa ou pote.","A cada hora, o outro sorteia um papel e os dois cumprem.","Entre uma e outra, deixem tempo livre para descansar.","No fim, escolham a atividade favorita para repetir."],"Misturem atividades calmas e animadas, para o dia ter ritmo.",null,"Quem organiza escreve as atividades; o outro só sorteia uma por hora."],
    "V2-290": ["Dia de hotel em casa: o outro vira hóspede","Tratar o outro como hóspede por um dia, com café na cama e pequenos mimos, é cuidado puro, quase sem custo.",["Quem organiza avisa só a data e prepara um 'cardápio' de serviços: café na cama, música, uma massagem nos pés, um filme.","O outro, o 'hóspede', escolhe pelo cardápio ao longo do dia.","Tudo vale: toalha dobrada, bilhetinho no travesseiro, luz baixa à noite.","Na hora do almoço e do jantar, sirvam algo simples, mas bem apresentado.","No fim, o hóspede deixa um 'comentário' carinhoso."],"Na próxima, troquem os papéis.",null,"Quem organiza prepara o cardápio e os mimos; o outro só descobre o que há."],
    "V2-291": ["Dia de festa-surpresa para dois, com convite e tema secreto","Uma festa de dois, com convite e tema, faz o dia parecer especial sem precisar de mais ninguém.",["Quem organiza escolhe em segredo um tema, como anos 80, praia ou noite de gala.","Entrega ao outro um convite de papel com a hora e a roupa.","Decorem a sala com o que há em casa.","Preparem comida simples ao tema, com música e um brinde.","Terminem com uma dança e uma foto juntos."],"O tema pode ser bobo: o importante é entrarem na brincadeira.",null,"Quem organiza escolhe o tema e escreve o convite; o outro só o recebe."],
    "V2-292": ["Tarde de mimos escolhidos pelo outro","Quando o outro escolhe os mimos, a gente descobre o quanto é conhecido e cuidado.",["Cada um escreve em segredo 3 mimos simples para o outro, como um chá, uma massagem nos ombros e uma música.","Troquem os papéis.","Cumpram os mimos ao longo da tarde, sem pressa.","Depois de cada mimo, o outro diz 'obrigado' e conta o que sentiu.","Fechem a tarde com um abraço longo."],"Se um mimo não agradar, o outro pode pedir uma troca com carinho.",null,"Cada um escolhe os mimos em segredo; só se descobre ao receber."],
    "V2-293": ["Tarde de rota secreta a pé ou de bicicleta","Seguir uma rota que só o outro conhece é uma pequena aventura, com a graça de não saber o fim.",["Quem organiza traça, em segredo, uma rota de 3 horas com 3 paradas bonitas.","O outro só sabe a hora e se precisa de roupa confortável.","Sigam a rota juntos, parando em cada ponto para um lanche ou uma foto.","A cada parada, quem organiza conta uma curiosidade ou uma memória.","Terminem no lugar mais bonito do caminho."],"Combinem de antemão o ritmo e um sinal de 'preciso de uma pausa'.",null,"Quem organiza traça a rota em segredo; o outro só segue."],
    "V2-294": ["Tarde de cafés ao ar livre: o outro escolhe o 'sinal'","Brincar com um sinal secreto torna a tarde um jogo de atenção, e o café ao ar livre dá o clima.",["Combinem 3 sinais, como uma mão no ombro, um toque no nariz e um sorriso.","Cada um escolhe, em segredo, o lugar onde cada sinal acontece.","Passeiem pelo bairro e, a cada sinal, parem para um pequeno gesto de carinho.","Escolham um café ou banco ao ar livre para a parada principal.","No fim, cada um adivinha qual sinal foi o preferido do outro."],"Combinem de antemão que os sinais são sempre carinhosos e discretos.",null,"Cada um combina os sinais em segredo; o outro só os descobre no caminho."],
    "V2-295": ["Dia da escolha em dados: o dado decide cada rumo","Deixar o dado escolher é uma forma leve de abandonar o controle e se surpreender juntos.",["Quem organiza prepara uma lista de 6 opções de lugares ou ações de graça, numeradas de 1 a 6.","Levem um dado, ou usem o do celular.","Jogue o dado e cumpram a opção sorteada.","A cada 2 horas, joguem de novo.","No fim, escolham a opção de que mais gostaram para repetir."],"Se sair algo que não dá, joguem outra vez, sem culpa.",null,"Quem organiza escolhe as 6 opções em segredo; o dado decide o rumo."],
    "V2-296": ["Tarde de lojas e jardins com bilhete-roteiro","Um bilhete com o roteiro da tarde guia o passeio e deixa quem recebe curioso sem estragar a surpresa.",["Quem organiza escolhe 3 lugares para olhar, como uma loja, um jardim e uma livraria.","Escreve um bilhete para cada um, com uma tarefa leve.","Os dois seguem o roteiro e abrem um bilhete por lugar.","Contem, em cada parada, o que mais gostaram de ver.","Terminem num banco, com o último bilhete."],"Só olhar e conversar: não é preciso comprar nada.",null,"Quem organiza escolhe os lugares e escreve os bilhetes; o outro só abre um por parada."],
    "V2-297": ["Tarde de cantinho escolhido: cada um arruma um canto para o outro","Arrumar um cantinho bonito para o outro é um gesto de carinho que transforma a casa e a tarde.",["Cada um escolhe, em segredo, um canto da casa para arrumar para o outro: uma poltrona, uma janela, uma mesa.","Separem a tarde em duas partes: primeiro arruma um, depois o outro.","Usem o que há: mantas, almofadas, velas ou flores simples.","Quando acabarem, levem o outro com os olhos fechados até o canto.","Fiquem um tempo juntos em cada canto, com um chá ou uma música."],"Evitem velas se tiver bichos ou crianças pequenas; usem uma luminária baixa.",null,"Cada um arruma o seu canto em segredo; o outro só o vê no final."],
    "V2-298": ["Dia de bilhetes de manhã, tarde e noite","Três bilhetes, um por período do dia, bastam para o dia inteiro ganhar um fio condutor, sem exigir muita produção.",["Quem organiza escreve 3 bilhetes: um para a manhã, um para a tarde e um para a noite.","Cada bilhete traz um lugar de graça ou uma atividade simples.","De manhã, abram o primeiro e cumpram juntos.","À tarde, o segundo, e à noite, o terceiro, com um fechamento carinhoso.","Antes de dormir, contem o momento favorito do dia."],"Uma pausa de descanso no meio ajuda muito.",null,"Quem organiza escreve os bilhetes; o outro só os abre na hora de cada um."],
  },
  es: {
    "V2-252": ["Puesta de sol para dos, sin pantallas y con un agradecimiento","Ver cómo el cielo cambia de color uno junto al otro calma el ritmo y deja espacio para decir «gracias» sin prisa.",["Mirad a qué hora se pone el sol y llegad 15 minutos antes a un lugar abierto, como una plaza, un muro o un mirador.","Dejad el móvil en el bolsillo y sentaos cerca.","Mientras el sol baja, cada uno dice en voz baja una cosa que le agradece al otro esta semana.","Quedaos en silencio hasta que se acabe la luz, de la mano.","Volved andando despacio, sin hablar de tareas."],"Llevad una chaqueta: al final de la tarde refresca rápido.",null,null],
    "V2-253": ["Paseo hasta el lugar donde todo empezó","Volver al lugar del principio os recuerda por qué os elegisteis y trae de vuelta la ligereza de los comienzos.",["Elegid un lugar de vuestra historia: donde os visteis por primera vez, donde os besasteis o donde hablasteis toda la noche.","Id andando, contando por el camino lo que cada uno recuerda de aquel día.","Al llegar, parad cinco minutos y decid lo que sentíais entonces.","Después, cada uno dice lo que ama del otro hoy y que no existía allá atrás.","Haceos una foto juntos, desde el mismo ángulo de entonces, si tenéis la antigua."],"Si el lugar ha cambiado o ha cerrado, quedaos fuera: el recuerdo vale igual.",null,null],
    "V2-254": ["Banco de jardín y una carta leída en voz alta","Escribir y leer en voz alta dice más que una conversación al vuelo, y el jardín lo deja todo más tranquilo.",["Escribid, cada uno en casa, una carta corta para el otro, con tres cosas que valoráis.","Llevad las cartas y elegid un banco tranquilo en un jardín o un parque.","Sentaos uno al lado del otro y leed, uno cada vez, sin interrumpir.","Después de cada carta, el otro solo responde «gracias» y con un abrazo.","Guardad las cartas para releerlas el mes que viene."],"Si os da vergüenza leer, intercambiad las cartas y leedlas en silencio, de la mano.",null,null],
    "V2-255": ["Vuelta por el barrio agradeciendo lo que ya tenemos","Fijarse en lo que ya es bueno en vuestra vida, una calle tras otra, acerca más que desear lo que falta.",["Salid a dar una vuelta de una hora por el barrio, sin destino.","En cada esquina, uno señala algo que agradece: la panadería, el árbol, el vecino simpático.","En la esquina siguiente, le toca al otro.","A mitad del paseo, parad y decid un agradecimiento solo para el otro.","Terminad en casa con un abrazo largo."],"Si se convierte en queja, volved al juego: solo vale agradecer.",null,null],
    "V2-256": ["Tarde de jardín público para hablar del futuro","Hablar de sueños paseando entre plantas y sombra hace el tema más ligero y que cada uno se sienta escuchado.",["Elegid un jardín público y llegad sin prisa, con agua y un tentempié sencillo.","Caminad unos 30 minutos en silencio, solo mirando y disfrutando.","Sentaos y que cada uno cuente un sueño para dentro de cinco años, sin juzgar.","Elegid juntos un pequeño paso que podáis empezar este mes.","Escribid el paso en un papel y llevadlo a casa."],"Cualquiera de los dos puede pedir un rato de silencio cuando quiera.",null,null],
    "V2-257": ["Tarde de mirador y carta para dentro de un año","Desde arriba la ciudad parece pequeña, y los problemas también; es un buen sitio para escribirle al futuro.",["Elegid un mirador o un lugar alto y llegad andando o en transporte público.","Que cada uno lleve papel y boli.","Arriba, mirad el paisaje durante diez minutos sin hablar.","Escribid una carta para la pareja que seréis dentro de un año, con deseos y promesas sencillas.","Doblad las cartas y acordad la fecha para abrirlas."],"Apuntad en el calendario el día de abrir las cartas, para no olvidarlo.",null,null],
    "V2-258": ["Hora de observar gente e inventar historias en un banco","Inventar la vida de quien pasa da risa y enseña cómo ve el mundo cada uno, gratis y sin preparar nada.",["Elegid un banco con buenas vistas a la gente que pasa, como en una plaza o en una avenida.","Cada uno elige a una persona a lo lejos e inventa su nombre, su profesión y su día.","Turnaos con los personajes durante una hora, sin señalar ni mirar fijamente a nadie.","Votad la historia más divertida y la más romántica.","A la vuelta, inventad la historia de vosotros dos, como si la contaran otros."],"Respetad a la gente: nada de burlas, solo historias cariñosas.",null,null],
    "V2-259": ["Hora de patos y pájaros en el parque, en silencio","Mirar a los animales con calma frena el ritmo y os obliga a estar en el presente, uno junto al otro.",["Elegid un lago, un jardín o un parque con patos y pájaros.","No llevéis pan ni restos de comida: a los animales no se les da de comer, solo se les observa.","Sentaos en silencio durante 15 minutos y contad cuántas especies habéis visto.","Cada uno elige su animal favorito del día y explica por qué.","Terminad dando un paseo tranquilo alrededor del agua."],"Cuanto más quietos estéis, más animales aparecerán: armaos de paciencia.",null,null],
    "V2-260": ["Caza de colores por el barrio, con fotos","Buscar un color cada vez cambia la mirada sobre calles que ya conocéis y se convierte en una pequeña competición ligera.",["Acordad cinco colores: rojo, azul, amarillo, verde y uno sorpresa.","Salid a pasear una hora y haced una foto de algo de cada color.","Quien lo encuentre primero se anota un punto, pero cuenta también la foto más bonita.","Sentaos y enseñaos las fotos, contando por qué elegisteis cada una.","Elegid juntos la mejor foto del día."],"Guardad las fotos en un álbum solo vuestro.",null,null],
    "V2-261": ["Dos calles que nunca hemos recorrido","Cambiar el camino de siempre por dos calles nuevas da la sensación de un pequeño viaje sin salir del barrio.",["Cada uno elige una calle que nunca haya recorrido, cerca de casa.","Caminad por la primera e id contando lo que notáis de distinto.","Después seguid por la segunda y comparad las dos.","Votad la calle más bonita y la más curiosa.","Apuntad la favorita para volver otro día."],"Llevad agua y una chaqueta ligera: el paseo puede dar más de sí de lo previsto.",null,null],
    "V2-262": ["Picnic de la hora azul al atardecer","La luz del final del día lo embellece todo, y un picnic sencillo se convierte en una escena de película casi sin gastar nada.",["Quien organiza prepara una cesta pequeña con cosas sencillas que ya tenga en casa.","El otro solo sabe la hora y el punto de encuentro.","Al llegar, extended una manta y sentaos frente al cielo.","Comed despacio viendo cómo la luz pasa del dorado al azul.","Terminad con una frase de cada uno sobre lo que más le ha gustado del día."],"Llevad una lucecita pequeña para la vuelta, por si oscurece.",null,"Quien organiza elige el lugar y la cesta en secreto; el otro solo lo descubre al llegar."],
    "V2-263": ["Mini caza fotográfica con tres retos secretos","Los retos cortos convierten un paseo normal en un juego, y las fotos se quedan como recuerdo sin coste.",["Quien organiza escribe tres retos en papelitos cerrados, como «algo redondo», «algo que te hace sonreír» y «algo que nos recuerda a nosotros».","Salid a dar un paseo de una hora.","Abrid un reto cada vez y fotografiad la respuesta.","Al final, enseñaos las fotos y explicad vuestras elecciones.","Votad la más creativa."],"Elegid retos fáciles, para que la gracia esté en la elección y no en la dificultad.",null,"Quien organiza esconde los retos; el otro solo los descubre al abrir cada papel."],
    "V2-264": ["Paseo en el que el otro elige cada curva","Dejar el rumbo en manos del otro es un pequeño gesto de confianza, y el camino se vuelve una sorpresa para los dos.",["Acordad una hora de paseo y un punto de partida.","En cada esquina, quien lidera dice izquierda, derecha o recto.","Quien sigue no pregunta adónde van.","A mitad de camino, cambiad: ahora el otro elige las curvas.","Terminad en un banco y contaos qué es lo más bonito que habéis visto."],"Acordad de antemano que sea un recorrido sin peligro y sin calles oscuras.",null,"Quien lidera elige las curvas sobre la marcha; el otro solo acompaña."],
    "V2-265": ["Un día del amanecer al atardecer: una nota para cada hora","Un día entero con una nota por hora hace que la sorpresa dure y convierte cada hora en una pequeña escena.",["Quien organiza escribe ocho notas, una para cada hora del día, con un lugar o una acción sencilla.","Por la mañana, ved salir el sol o tomad un café en la calle.","Abrid una nota por hora y cumplidla con calma.","Alternad paseos, pausas y conversaciones.","Al ponerse el sol, entregad la última nota: una frase de amor."],"Dejad una hora libre en medio, para que el día respire.",null,"Quien organiza prepara las notas; el otro solo abre una cada hora."],
    "V2-266": ["Día de mapa del tesoro: pistas por la ciudad","Seguir pistas por lugares conocidos hace que la ciudad parezca nueva y da un día de aventura ligera.",["Quien organiza dibuja un mapa sencillo con cinco paradas, cada una con una pista.","Cada parada es un lugar gratuito, como una plaza, un mirador o un jardín.","En la primera parada, abrid la primera pista.","En cada lugar, haced lo que pida la pista: contar un recuerdo, hacer una foto, decir un piropo.","Al final, el tesoro es un picnic o un abrazo acordado."],"Guardad el mapa: se convertirá en un recuerdo.",null,"Quien organiza elige las paradas y las pistas; el otro solo sigue."],
    "V2-267": ["Día de picnic misterioso con tres paradas","Un picnic repartido en tres paradas da ritmo al día y hace crecer la sorpresa.",["Quien organiza esconde tres momentos: aperitivo, plato principal y postre, cada uno en un lugar.","Los dos caminan entre los lugares, charlando.","En cada parada, abrid una nota que diga qué hacer.","Comed despacio y disfrutad del sitio.","Volved a casa sin prisa, de la mano."],"Llevad una manta y una bolsa para la basura: dejadlo todo limpio.",null,"Quien organiza elige las paradas y el menú; el otro solo descubre una cada vez."],
    "V2-268": ["Día de cafeterías y libros: una nota en cada parada","Pasar un día entre cafeterías tranquilas y estanterías de libros, con notas escondidas, mezcla lo acogedor con la sorpresa.",["Quien organiza elige cuatro lugares que os gusten, como una cafetería, una biblioteca y una librería.","Escribe una nota para cada parada, con un piropo, una pregunta o una tarea.","En cada lugar, abrid la nota y leedla en voz alta.","Elegid un libro o una página para leer juntos en voz baja.","Terminad el día con una nota de despedida."],"En librerías y cafeterías, leed y pedid solo lo que os apetezca; sin presión para comprar.",null,"Quien organiza escribe las notas; el otro solo abre una por parada."],
    "V2-269": ["Día de tiendas y mercadillos solo para mirar, con misiones secretas","Pasear por mercadillos y tiendas sin comprar se convierte en un juego, y las misiones hacen el día ligero y curioso.",["Quien organiza prepara cinco misiones, como «encuentra algo que le pegue al otro» o «busca el objeto más antiguo».","Id a mercadillos y tiendas de segunda mano, solo a mirar.","Abrid una misión en cada parada y cumplidla juntos.","Guardad las respuestas en fotos, sin comprar nada.","Al final, elegid el hallazgo favorito y reíd con las elecciones."],"Si alguno de los dos quiere llevarse algo, vale: la regla es solo no necesitarlo.",null,"Quien organiza escribe las misiones; el otro solo descubre una cada vez."],
    "V2-270": ["Día de museos y jardines gratuitos, con sorteo de ruta","Dejar que decida el azar quita la presión de elegir y da al día un toque de aventura.",["Quien organiza apunta seis lugares gratuitos o de entrada libre en la ciudad.","Escribid los nombres en papelitos doblados.","En cada parada, sortead el siguiente lugar.","En cada sitio, elegid juntos algo para mirar con calma y comentarlo.","Terminad el día en el último lugar sorteado, con un tentempié."],"Comprobad los horarios antes de salir, para no encontraros la puerta cerrada.",null,"Quien organiza apunta los lugares; el sorteo decide el resto sobre la marcha."],
    "V2-271": ["Turistas en nuestro propio barrio: una hora con guía inventado","Mirar el barrio como un visitante revela detalles que el día a día esconde, y el juego del guía lo hace todo más ligero.",["Elegid quién es el guía y quién el turista, y acordad una hora de paseo.","El guía enseña el barrio como si fuera un lugar turístico, inventando historias.","El turista hace preguntas curiosas y saca fotos.","A mitad del paseo, cambiad los papeles.","Terminad en un banco, valorando el paseo con una nota del 0 al 10."],"Nada de gastar: el premio es la risa.",null,null],
    "V2-272": ["Hora de murales y arte urbano: cada uno elige su preferido","Buscar arte en las paredes de la ciudad entrena la mirada y muestra el gusto de cada uno sin necesidad de explicaciones.",["Elegid una calle o un barrio con murales y arte urbano.","Caminad despacio, mirando las paredes.","Cada uno elige su preferido y explica lo que siente al verlo.","Fotografiad los dos elegidos, uno al lado del otro.","Votad el más bonito y el más raro."],"Respetad a los vecinos: observad sin tocar y sin molestar.",null,null],
    "V2-273": ["Lectura en voz alta en una librería: un fragmento para el otro","Leerle un fragmento a quien queremos es un cariño barato y muy íntimo, y la librería pone el ambiente perfecto.",["Cada uno elige un libro de la estantería, sin comprarlo.","Buscad un fragmento bonito o gracioso, de una o dos páginas.","En un rincón tranquilo, leed en voz baja, el uno al otro.","Después de cada lectura, contad por qué elegisteis ese fragmento.","Salid juntos, comentando cuál ha sido el favorito."],"Leed bajito, para no molestar a quien esté cerca.",null,null],
    "V2-274": ["Visita a un lugar de nuestra historia y una frase de agradecimiento","Volver a un lugar importante y decir «gracias» allí une el recuerdo con el cariño de hoy.",["Elegid un lugar que os marcó, como la primera cafetería o la primera calle por la que paseasteis juntos.","Id sin prisa, recordando el camino.","Allí, cada uno dice una frase de agradecimiento al otro, mirándole a los ojos.","Contad lo que significa hoy ese lugar para vosotros.","Acordad volver allí un día especial."],"Una foto sin posar, de la mano, cierra bien el momento.",null,null],
    "V2-275": ["Una hora en la biblioteca: elegir un libro para leer juntos","Elegir juntos un libro para leer es un pequeño plan de futuro, gratis, y da conversación para muchas noches.",["Id a la biblioteca y pasead entre las estanterías sin prisa.","Cada uno le presenta al otro un libro que le guste, en un minuto.","Elegid uno solo para leerlo los dos, por capítulos.","Si podéis pedirlo prestado, acordad el día de lectura de la semana.","Terminad sentados, leyendo juntos la primera página."],"Si la biblioteca no tiene el libro, apuntad el título y buscadlo en otra.",null,null],
    "V2-276": ["Calendario de dos: fijar tres citas futuras en un banco","Planear juntos las próximas citas os da algo que esperar y demuestra que los dos queréis seguir.",["Elegid un banco, una cafetería o un jardín tranquilo.","Llevad la agenda o el calendario del móvil.","Cada uno propone una idea de cita, gratis o barata.","Fijad tres fechas para las próximas semanas y apuntadlas en el calendario.","Brindad con agua, café o té por lo acordado."],"Elegid fechas realistas: las citas pequeñas y seguras valen más que las grandes e inciertas.",null,null],
    "V2-277": ["Tarde de teatrillo en casa: un número secreto de cada uno","Preparar un número secreto para el otro mezcla nervios, risas y cariño en una tarde solo vuestra.",["Acordad en secreto: cada uno prepara un número de tres a cinco minutos, como una mímica, una canción o una historia.","Separaos durante una hora para ensayar, cada uno en una habitación.","Montad un escenario sencillo en el salón, con una cortina hecha con una sábana.","Actuad, uno cada vez, con aplauso incluido.","Votad el número más gracioso y el más emocionante."],"Quien más se equivoque gana el premio al «más valiente».",null,"Cada uno prepara su número en secreto; no se descubre hasta el momento de actuar."],
    "V2-278": ["Tarde de cartas escondidas por la casa: una por hora","Las cartas que aparecen de una en una hacen que la tarde dé cariño en pequeñas dosis.",["Quien organiza escribe cuatro cartas cortas, cada una con un piropo, un recuerdo o una tarea ligera.","Esconde las cartas por la casa, antes de que llegue el otro.","Cada hora, el otro busca una carta, con una pista.","Cada carta se lee en voz alta y se responde con un gesto.","En la última, el mensaje es: «ven a buscarme»."],"Elegid escondites seguros, sin molestar a nadie de la casa.",null,"Quien organiza esconde las cartas; el otro solo busca una por hora."],
    "V2-279": ["Tarde de cata a ciegas con lo que hay en la despensa","Probar con los ojos cerrados cambia el sabor y da risa, y solo usa lo que ya tenéis en casa.",["Quien organiza separa seis cosas de la despensa, como una fruta, un queso, un pan, un chocolate, una especia y un dulce.","El otro se sienta con los ojos vendados.","Dale cada cosa en porciones pequeñas, y el otro intenta adivinarla.","Cambiad los papeles.","Contad quién ha acertado más y comeos juntos lo que más os guste."],"Comprobad antes alergias y preferencias, y nada de cosas que al otro no le gusten.",null,"Quien organiza elige las cosas en secreto; el otro solo prueba y adivina."],
    "V2-280": ["Una nota escondida en un banco del jardín","Una nota esperando en un lugar acordado convierte un paseo corto en un regalo.",["Quien organiza escribe una nota cariñosa y la esconde en un banco, o la lleva en el bolsillo.","Invita al otro a una hora de paseo por un jardín o un parque.","Pasead y, cuando lleguéis al banco, pídele al otro que busque.","El otro lee la nota en voz alta y responde con un abrazo.","Quedaos un rato sentados, en silencio."],"Si escondéis la nota, usad un sitio donde no moleste a nadie, y recoged el papel después.",null,"Quien organiza esconde la nota; el otro solo la descubre en el banco."],
    "V2-281": ["Buscar el rincón más bonito del barrio, elegido en secreto","Elegir un rincón bonito para el otro demuestra cuánto nos fijamos en quien queremos.",["Cada uno elige, en secreto, un rincón del barrio que le parezca bonito.","Acordad una hora de paseo.","Cada uno lleva al otro hasta su lugar, sin decir dónde es.","En cada lugar, contad por qué lo elegisteis.","Fotografiad los dos rincones y elegid el más especial."],"Pueden ser sitios sencillos: un banco, una ventana, un árbol.",null,"Cada uno elige su rincón en secreto; el otro solo lo descubre al llegar."],
    "V2-282": ["Libro sorpresa: uno elige la página, el otro la lee en voz alta","Leer una página elegida por el otro es una sorpresa pequeña, íntima y gratuita.",["Id a una biblioteca o a una estantería de libros de casa.","Quien organiza elige en secreto un libro y una página bonita.","El otro lee la página en voz alta, sin haberla visto antes.","Hablad de lo que os ha parecido y de lo que habéis sentido.","Cambiad los papeles."],"Elegid textos cortos y amables: la lectura resulta más ligera.",null,"Quien organiza elige el libro y la página en secreto; el otro solo lee en el momento."],
    "V2-283": ["Tarde de puesta de sol, banco y termo de té","Un té caliente, un banco y el cielo cambiando hacen que la tarde dé una conversación buena y pausada.",["Preparad un termo de té o de café y llevad dos vasos.","Elegid un banco o un muro con vistas abiertas.","Llegad antes de la puesta de sol y sentaos frente al cielo.","Hablad del día, sin prisa y sin pantallas.","Cuando oscurezca, volved andando del brazo."],"Llevad una mantita pequeña: el banco se enfría enseguida.",null,null],
    "V2-284": ["Tarde en bici sin prisa hasta un mirador","Pedalear despacio uno al lado del otro da tiempo para charlar y para mirar la ciudad desde otro ángulo.",["Elegid un trayecto tranquilo, a ser posible por carril bici o por una calle calmada.","Llevad agua y un tentempié sencillo.","Pedalead a ritmo de conversación, sin competir.","Parad en un mirador o en un jardín y descansad un poco.","Volved con calma, sin prisa y con atención al tráfico."],"Si uno de los dos no tiene bici, podéis hacer el mismo recorrido andando.",null,null],
    "V2-285": ["Tarde en el jardín sin prisa: ponerles nombre a flores y árboles","Dar nombre a lo que vemos, aunque sea inventado, nos hace mirar con cariño y reír juntos.",["Elegid un jardín o un parque con mucho verde.","Llevad una libreta pequeña y un boli.","Cada uno le pone un nombre inventado a una flor o a un árbol y explica su elección.","Apuntad los nombres y dibujad rápido, sin preocuparos por el talento.","Terminad en el banco más bonito, leyendo la lista en voz alta."],"Respetad las plantas: mirar y dibujar, sin arrancar nada.",null,null],
    "V2-286": ["Tarde de música callejera y conciertos gratuitos","Escuchar música en directo, sin prisa y sin entrada, hace la tarde más bonita y da conversación gratis.",["Buscad una plaza, un jardín o una calle donde suela haber música en directo, o un concierto gratuito.","Llegad sin expectativas y escuchad de pie o sentados.","Cada uno elige la canción que más le ha gustado y cuenta por qué.","Si os apetece, bailad un poco, de la mano.","Terminad con un paseo, tarareando la favorita."],"Si lleváis algo de suelto, podéis dejar un gesto de cariño al artista, pero sin obligación.",null,null],
    "V2-287": ["Paseo por las casas de nuestros sueños: mirar desde fuera e imaginar","Imaginar dónde viven los sueños de la pareja es una forma divertida de hablar del futuro sin compromiso.",["Elegid un barrio bonito con casas o edificios que os guste mirar.","Pasead despacio, mirando las fachadas.","Cada uno elige la casa de sus sueños y explica por qué.","Imaginad juntos cómo sería la vida allí: la cocina, el jardín, el balcón.","Fotografiad las favoritas y elegid una para el «sueño de la pareja»."],"Respetad la privacidad de quien vive allí: mirad sin acercaros a las ventanas.",null,null],
    "V2-288": ["Tarde en un refugio de animales: voluntariado de paseo y cariño","Cuidar de animales que esperan un hogar une a la pareja y da sentido a la tarde.",["Buscad un refugio de animales de la zona y acordad la visita de antemano, preguntando si aceptan voluntarios.","Llegad a la hora acordada y seguid las normas del lugar.","Ayudad con lo que os pidan, como pasear perros o dar cariño a los gatos.","Hablad de la experiencia de vuelta a casa.","Acordad volver otra tarde."],"Solo adoptad si los dos estáis listos y lo habéis hablado antes con calma.",null,null],
    "V2-289": ["Día de cápsulas sorpresa: una actividad escondida cada hora","Pasar un día en casa con una actividad secreta cada hora evita que se haga monótono y mantiene viva la curiosidad.",["Quien organiza escribe 6 actividades en papelitos doblados, usando solo lo que hay en casa, como bailar, cocinar algo sencillo o leer en voz alta.","Mete los papelitos en una caja o en un tarro.","Cada hora, la otra persona saca un papel y lo cumplís los dos.","Entre una actividad y otra, dejad un rato libre para descansar.","Al final, elegid vuestra actividad favorita para repetirla."],"Mezclad actividades tranquilas y animadas, para que el día tenga ritmo.",null,"Quien organiza escribe las actividades; la otra persona solo saca una cada hora."],
    "V2-290": ["Día de hotel en casa: la otra persona es la huésped","Tratar a la otra persona como una huésped durante un día, con desayuno en la cama y pequeños mimos, es puro cariño y casi no cuesta nada.",["Quien organiza avisa solo de la fecha y prepara una «carta» de servicios: desayuno en la cama, música, un masaje de pies, una peli.","La persona huésped va eligiendo de la carta a lo largo del día.","Todo vale: una toalla doblada con gracia, una notita en la almohada, luz tenue por la noche.","A la hora de comer y de cenar, servid algo sencillo, pero bien presentado.","Al final, la persona huésped deja una «reseña» cariñosa."],"La próxima vez, cambiad los papeles.",null,"Quien organiza prepara la carta y los mimos; la otra persona solo descubre lo que hay."],
    "V2-291": ["Día de fiesta sorpresa para dos, con invitación y temática secreta","Una fiesta para dos, con invitación y temática, hace que el día se sienta especial sin necesitar a nadie más.",["Quien organiza elige en secreto una temática, como los años 80, la playa o una noche de gala.","Le entrega a la otra persona una invitación en papel con la hora y el vestuario.","Decorad el salón con lo que tengáis por casa.","Preparad comida sencilla acorde con la temática, con música y un brindis.","Terminad con un baile y una foto juntos."],"La temática puede ser una tontería: lo importante es entrar en el juego.",null,"Quien organiza elige la temática y escribe la invitación; la otra persona solo la recibe."],
    "V2-292": ["Tarde de mimos elegidos por la otra persona","Cuando la otra persona elige los mimos, descubrís cuánto os conocéis y os cuidáis.",["Cada uno escribe en secreto 3 mimos sencillos para el otro, como una infusión, un masaje en los hombros y una canción.","Intercambiad los papeles.","Cumplid los mimos a lo largo de la tarde, sin prisa.","Después de cada mimo, la persona que lo recibe da las gracias y cuenta cómo se ha sentido.","Cerrad la tarde con un abrazo largo."],"Si un mimo no le convence, puede pedir un cambio con cariño.",null,"Cada uno elige los mimos en secreto; solo se descubren al recibirlos."],
    "V2-293": ["Tarde de ruta secreta a pie o en bici","Seguir una ruta que solo conoce la otra persona es una pequeña aventura, con el encanto de no saber cómo acaba.",["Quien organiza traza, en secreto, una ruta de unas 3 horas con 3 paradas bonitas.","La otra persona solo sabe la hora y si necesita ropa cómoda.","Seguid la ruta juntos, parando en cada punto para merendar o hacer una foto.","En cada parada, quien organiza cuenta una curiosidad o un recuerdo.","Acabad en el lugar más bonito del recorrido."],"Acordad de antemano el ritmo y una señal para decir «necesito una pausa».",null,"Quien organiza traza la ruta en secreto; la otra persona solo la sigue."],
    "V2-294": ["Tarde de cafés al aire libre: la otra persona elige la «señal»","Jugar con una señal secreta convierte la tarde en un juego de atención, y el café al aire libre pone el ambiente.",["Acordad 3 señales, como una mano en el hombro, un toque en la nariz y una sonrisa.","Cada uno elige, en secreto, el sitio donde ocurre cada señal.","Pasead por el barrio y, con cada señal, parad para un pequeño gesto de cariño.","Elegid una cafetería con terraza o un banco al aire libre para la parada principal.","Al final, cada uno adivina qué señal fue la favorita del otro."],"Acordad de antemano que las señales sean siempre cariñosas y discretas.",null,"Cada uno acuerda las señales en secreto; el otro las descubre por el camino."],
    "V2-295": ["Día de decisiones a los dados: el dado marca cada rumbo","Dejar que decida el dado es una forma ligera de soltar el control y sorprenderos juntos.",["Quien organiza prepara una lista de 6 opciones de sitios o planes gratis, numeradas del 1 al 6.","Llevad un dado, o usad el del móvil.","Tirad el dado y cumplid la opción que salga.","Cada 2 horas, volved a tirar.","Al final, elegid la opción que más os haya gustado para repetirla."],"Si sale algo que no se puede hacer, tirad otra vez, sin culpa.",null,"Quien organiza elige las 6 opciones en secreto; el dado decide el rumbo."],
    "V2-296": ["Tarde de tiendas y jardines con nota-itinerario","Una nota con el itinerario de la tarde guía el paseo y deja a quien la recibe con curiosidad, sin desvelar la sorpresa.",["Quien organiza elige 3 sitios para visitar, como una tienda, un jardín y una librería.","Escribe una nota para cada sitio, con una tarea ligera.","Seguid el itinerario y abrid una nota en cada lugar.","En cada parada, contad lo que más os ha gustado ver.","Terminad en un banco, con la última nota."],"Solo mirar y charlar: no hace falta comprar nada.",null,"Quien organiza elige los sitios y escribe las notas; la otra persona solo abre una en cada parada."],
    "V2-297": ["Tarde de rinconcito elegido: cada uno prepara un rincón para el otro","Preparar un rincón bonito para la otra persona es un gesto de cariño que transforma la casa y la tarde.",["Cada uno elige, en secreto, un rincón de la casa para preparar para el otro: un sillón, una ventana, una mesa.","Dividid la tarde en dos partes: primero prepara uno y luego el otro.","Usad lo que tengáis: mantas, cojines, velas o flores sencillas.","Cuando terminéis, llevad al otro con los ojos cerrados hasta su rincón.","Quedaos un rato juntos en cada rincón, con una infusión o con música."],"Evitad las velas si hay mascotas o niños pequeños; usad una lamparita de luz tenue.",null,"Cada uno prepara su rincón en secreto; el otro solo lo ve al final."],
    "V2-298": ["Día de notas para la mañana, la tarde y la noche","Tres notas, una por cada parte del día, bastan para que la jornada tenga un hilo conductor sin exigir mucho montaje.",["Quien organiza escribe 3 notas: una para la mañana, otra para la tarde y otra para la noche.","Cada nota propone un sitio gratis o una actividad sencilla.","Por la mañana, abrid la primera y cumplidla juntos.","Por la tarde, la segunda, y por la noche, la tercera, con un cierre cariñoso.","Antes de dormir, contad cuál ha sido vuestro momento favorito del día."],"Una pausa para descansar a mitad del día ayuda mucho.",null,"Quien organiza escribe las notas; la otra persona solo las abre en el momento de cada una."],
  },
  en: {
    "V2-252": ["Sunset for two, no screens, one thank-you","Watching the sky change color side by side slows you down and makes room to say thank you without rushing.",["Check the sunset time and arrive 15 minutes early somewhere open, like a square, a low wall or a viewpoint.","Keep your phones in your pockets and sit close.","As the sun goes down, each of you quietly shares one thing you appreciated about the other this week.","Stay quiet until the light is gone, holding hands.","Walk home slowly, without talking about chores."],"Bring a jacket: it gets chilly fast once the sun drops.",null,null],
    "V2-253": ["A walk to where it all began","Going back to where it started reminds you why you chose each other and brings back that early lightness.",["Pick a place from your story: where you first saw each other, first kissed, or talked all night.","Walk there, sharing what each of you remembers about that day along the way.","When you arrive, pause for 5 minutes and say how you felt back then.","Then each say what you love about the other today that wasn't there yet.","Take a photo together from the same angle as before, if you still have the old one."],"If the place has changed or closed, just stand outside: the memory counts all the same.",null,null],
    "V2-254": ["A garden bench and a letter read aloud","Writing and reading aloud says more than rushed conversation, and a quiet garden softens everything.",["At home, each write the other a short letter naming 3 things you value.","Bring the letters and find a calm bench in a garden or park.","Sit side by side and read, one at a time, without interrupting.","After each letter, the listener only answers with a thank-you and a hug.","Keep the letters to reread next month."],"If reading aloud feels shy, swap letters and read them silently, holding hands.",null,null],
    "V2-255": ["A neighborhood stroll giving thanks for what we already have","Noticing what's already good in your life, one street at a time, brings you closer than wishing for what's missing.",["Head out for an hour's walk around the neighborhood, with no destination.","At each corner, one of you points out something you're grateful for: the bakery, a tree, the friendly neighbor.","At the next corner, it's the other one's turn.","Halfway through, stop and share one thank-you meant just for each other.","Finish at home with a long hug."],"If it turns into complaining, go back to the game: only thankfulness counts.",null,null],
    "V2-256": ["A public garden afternoon to talk about the future","Talking about dreams while wandering among plants and shade keeps the topic light and helps you both feel heard.",["Pick a public garden and arrive unhurried, with water and a simple snack.","Walk for about 30 minutes in silence, just looking and enjoying.","Sit down and each share one dream for five years from now, with no judgment.","Choose together one small step you can start this month.","Write the step on a piece of paper and take it home."],"Either of you can ask for quiet time whenever you want.",null,null],
    "V2-257": ["A viewpoint afternoon and a letter to a year from now","From up high, the city looks small and so do the worries, which makes it a lovely place to write to the future.",["Pick a viewpoint or high spot and get there on foot or by public transport.","Each of you brings paper and a pen.","At the top, take in the view for 10 minutes without talking.","Write a letter to the two of you a year from now, with simple wishes and promises.","Fold the letters and agree on the date to open them."],"Put the opening day in your calendar so you don't forget.",null,null],
    "V2-258": ["An hour of people-watching and making up stories on a bench","Imagining the lives of passersby makes you laugh and shows how each of you sees the world, free and with no prep.",["Pick a bench with a good view of people passing, like in a square or on a busy avenue.","Each of you chooses someone from afar and invents their name, job and day.","Take turns with the characters for an hour, without pointing or staring at anyone.","Vote for the funniest story and the most romantic one.","On the way back, invent the story of the two of you, as if others were telling it."],"Be respectful of people: no mockery, only kind stories.",null,null],
    "V2-259": ["An hour with ducks and birds in the park, in silence","Watching animals calmly slows you down and keeps you in the moment, side by side.",["Choose a pond, garden or park with ducks and birds.","Don't bring bread or leftovers: wildlife isn't for feeding, just for watching.","Sit quietly for 15 minutes and count how many kinds you spot.","Each pick your favorite creature of the day and explain why.","Finish with a slow walk around the water."],"The quieter you are, the more animals show up: bring patience.",null,null],
    "V2-260": ["A color hunt around the neighborhood, with photos","Looking for one color at a time changes how you see streets you already know and becomes a gentle little contest.",["Agree on 5 colors: red, blue, yellow, green and a surprise one.","Walk for an hour and photograph one thing of each color.","Whoever finds one first scores a point, but the prettiest photo counts too.","Sit down and show your photos, telling why you picked each one.","Choose the best photo of the day together."],"Keep the photos in an album just for the two of you.",null,null],
    "V2-261": ["Two streets we've never walked","Swapping your usual route for two new streets feels like a tiny trip without leaving the neighborhood.",["Each of you picks a street near home that you've never walked.","Stroll down the first one, sharing what you notice that's different.","Then take the second and compare the two.","Vote for the prettiest street and the most curious one.","Note your favorite so you can come back another day."],"Bring water and a light jacket: the walk might turn out longer than planned.",null,null],
    "V2-262": ["A blue-hour picnic at dusk","The light at the end of the day makes everything lovelier, and a simple picnic becomes a movie scene for almost nothing.",["The one planning packs a small basket of simple things you already have at home.","The other only knows the time and the meeting spot.","When you arrive, spread out a blanket and sit facing the sky.","Eat slowly while the light shifts from gold to blue.","Finish with one sentence each about what you liked most about the day."],"Bring a small light for the walk back if it gets dark.",null,"The planner picks the spot and the basket in secret; the other finds out only on arrival."],
    "V2-263": ["A mini photo hunt with three secret challenges","Short challenges turn an ordinary walk into a game, and the photos become keepsakes at no cost.",["The planner writes 3 challenges on folded papers, like 'something round', 'something that makes you smile' and 'something that reminds you of us'.","Head out for an hour's walk.","Open one challenge at a time and photograph your answer.","At the end, show your photos and explain your choices.","Vote for the most creative one."],"Keep the challenges easy, so the fun comes from the choosing rather than the difficulty.",null,"The planner hides the challenges; the other only finds out each one when opening its paper."],
    "V2-264": ["A walk where the other chooses every turn","Handing over the direction is a small act of trust, and the route becomes a surprise for both of you.",["Agree on an hour's walk and a starting point.","At each corner, the leader calls left, right or straight.","The follower doesn't ask where you're headed.","Halfway through, switch: now the other chooses the turns.","End on a bench and share the most beautiful thing you saw."],"Agree beforehand: no unsafe spots and no dark streets.",null,"The leader picks the turns on the spot; the other simply follows."],
    "V2-265": ["A sunrise-to-sunset day: one note for every hour","A whole day with a note each hour stretches the surprise out and turns every hour into a little scene.",["The planner writes 8 notes, one for each hour of the day, each with a place or a simple activity.","In the morning, watch the sunrise or have coffee outside.","Open one note per hour and carry it out unhurried.","Mix walks, breaks and conversations.","At sunset, hand over the last note: a love message."],"Leave one hour free in the middle, so the day can breathe.",null,"The planner prepares the notes; the other opens just one each hour."],
    "V2-266": ["A treasure-map day: clues around the city","Following clues through familiar places makes the city feel new and gives you a light, adventurous day.",["The planner draws a simple map with 5 stops, each with a clue.","Each stop is a free place, like a square, a viewpoint or a garden.","At the first stop, open the first clue.","At each place, do what the clue asks: share a memory, take a photo, give a compliment.","In the end, the treasure is a picnic or a hug you agreed on."],"Keep the map: it becomes a keepsake.",null,"The planner chooses the stops and the clues; the other simply follows."],
    "V2-267": ["A mystery picnic day with three stops","A picnic spread over three stops gives the day a rhythm and lets the surprise build.",["The planner hides three moments: starter, main and dessert, each in a different place.","You two walk between the spots, chatting.","At each stop, open a note that says what to do.","Eat slowly and enjoy the place.","Head home without hurry, holding hands."],"Bring a blanket and a bag for trash: leave everything clean.",null,"The planner chooses the stops and the menu; the other discovers one at a time."],
    "V2-268": ["A cafés-and-books day: one note at every stop","A day among quiet cafés and bookshelves, with hidden notes, blends coziness and surprise.",["The planner picks 4 places you both like, such as a café, a library and a bookshop.","Write a note for each stop, with a compliment, a question or a small task.","At each place, open the note and read it aloud.","Choose a book or a page to read quietly together.","End the day with a goodbye note."],"In bookshops and cafés, only read and order what you genuinely enjoy; there's no pressure to buy.",null,"The planner writes the notes; the other opens just one per stop."],
    "V2-269": ["A day of shops and markets just for browsing, with secret missions","Wandering through markets and shops without buying turns into a game, and the missions keep the day light and curious.",["The planner prepares 5 missions, like 'find something that suits the other' or 'spot the oldest object'.","Head to markets and secondhand shops, just to look.","Open one mission per stop and complete it together.","Record your answers in photos, without buying anything.","At the end, pick your favorite find and laugh over your choices."],"If one of you wants to take something home, that's fine: the rule is just not needing to.",null,"The planner writes the missions; the other finds out one at a time."],
    "V2-270": ["A day of free museums and gardens, with a lucky-draw route","Letting chance pick the route takes the pressure off choosing and adds a touch of adventure.",["The planner lists 6 free or open-entry places in the city.","Write the names on folded papers.","At each stop, draw the next place.","At each spot, choose one thing to look at calmly and talk about.","End the day at the last place you drew, with a snack."],"Check opening hours before leaving, so you don't find a closed door.",null,"The planner lists the places; the draw decides the rest on the spot."],
    "V2-271": ["Tourists in our own neighborhood: an hour with an invented guide","Seeing your neighborhood like a visitor reveals details everyday life hides, and the guide game keeps it light.",["Decide who is the guide and who is the tourist, and agree on an hour's walk.","The guide presents the neighborhood like a tourist attraction, making up stories.","The tourist asks curious questions and takes photos.","Halfway through, swap roles.","End on a bench, rating the tour from 0 to 10."],"No spending needed: the prize is the laughter.",null,null],
    "V2-272": ["An hour of murals and street art: each picks a favorite","Hunting for art on the city's walls trains your eye and shows each other's taste without needing explanations.",["Choose a street or neighborhood with murals and street art.","Walk slowly, looking at the walls.","Each pick a favorite and explain what you feel looking at it.","Photograph both picks side by side.","Vote for the most beautiful and the strangest."],"Be respectful of residents: look without touching and without getting in the way.",null,null],
    "V2-273": ["Reading aloud in a bookshop: a passage for each other","Reading a passage to someone you love is a free, very intimate gesture, and a bookshop sets the perfect mood.",["Each of you picks a book from the shelf, with no need to buy.","Find a beautiful or funny passage, a page or two long.","In a quiet corner, read to each other in low voices.","After each reading, tell why you chose that passage.","Leave together, chatting about which one you liked best."],"Read softly, so you don't disturb the people nearby.",null,null],
    "V2-274": ["A visit to a place from our story, with a thank-you","Going back to an important place and saying 'thank you' there ties the memory to the affection you share today.",["Pick a place that marked you both, like the first café or the first street you walked together.","Go unhurried, remembering the way.","At the spot, each say one sentence of thanks to the other, looking into each other's eyes.","Share what the place means to you now.","Agree to return on a special day."],"An unposed photo, holding hands, is a lovely way to close the moment.",null,null],
    "V2-275": ["An hour at the library: choosing a book to read together","Choosing a book to read together is a small plan for the future, free of charge, and gives you something to talk about for many evenings.",["Go to the library and wander the shelves, unhurried.","Each present a book you love to the other in one minute.","Pick just one for you both to read, chapter by chapter.","If you can borrow it, set a reading day each week.","Finish seated, reading the first page together."],"If the library doesn't have the book, note the title and look elsewhere.",null,null],
    "V2-276": ["Our calendar: booking three future dates on a bench","Planning your next dates together gives you something to look forward to and shows you both want to keep going.",["Pick a bench, a café or a quiet garden.","Bring your planner or phone calendar.","Each suggest a date idea, free or low-cost.","Choose three dates over the coming weeks and put them in the calendar.","Toast the plan with water, coffee or tea."],"Pick realistic dates: small and certain beats big and uncertain.",null,null],
    "V2-277": ["A home theater afternoon: a secret act from each of you","Preparing a secret act for each other mixes nerves, laughter and affection into an afternoon that's all yours.",["Agree in secret: each prepares a 3 to 5 minute act, like a mime, a song or a story.","Split up for an hour to rehearse, each in a different room.","Set up a simple stage in the living room, with a bedsheet curtain.","Perform one at a time, with applause.","Vote for the funniest act and the most moving one."],"Whoever slips up the most wins the 'bravest' award.",null,"Each prepares the act in secret; it's only revealed at showtime."],
    "V2-278": ["An afternoon of letters hidden around the house: one per hour","Letters that turn up one at a time make the afternoon last, with affection in small doses.",["The planner writes 4 short letters, each with a compliment, a memory or a light task.","Hide the letters around the house before the other arrives.","Every hour, the other searches for one letter, with a hint.","Each letter is read aloud and answered with a gesture.","The last one says: 'come find me'."],"Choose safe hiding spots that don't disturb anyone else at home.",null,"The planner hides the letters; the other searches for one each hour."],
    "V2-279": ["A blind tasting afternoon with what's in the pantry","Tasting with your eyes closed changes the flavors and makes you laugh, and uses only what you already have at home.",["The planner picks 6 pantry items, like a fruit, a cheese, a bread, a chocolate, a spice and a sweet.","The other sits blindfolded.","Offer each item in small bites, and the other tries to guess.","Swap roles.","Count who guessed the most and eat your favorites together."],"Check for allergies and preferences first, and skip anything the other doesn't like.",null,"The planner picks the items in secret; the other only tastes and guesses."],
    "V2-280": ["A note hidden on a garden bench","A note waiting in an agreed spot turns a short stroll into a gift.",["The planner writes a loving note and hides it on a bench, or keeps it in a pocket.","Invite the other for an hour's walk in a garden or park.","Stroll, and when you reach the bench, ask the other to look.","The other reads the note aloud and answers with a hug.","Stay seated a while, in silence."],"If you hide the note, use a spot that doesn't bother anyone, and take the paper with you afterward.",null,"The planner hides the note; the other only finds it at the bench."],
    "V2-281": ["Finding the prettiest spot in the neighborhood, chosen in secret","Picking a lovely corner for the other shows how closely you notice the person you love.",["Each secretly chooses a spot in the neighborhood they find beautiful.","Agree on an hour's walk.","Each leads the other to their spot, without saying where it is.","At each place, share why you chose it.","Photograph both spots and pick the most special one."],"Simple places work: a bench, a window, a tree.",null,"Each chooses their spot in secret; the other only finds out on arrival."],
    "V2-282": ["Surprise book: one picks the page, the other reads aloud","Reading a page the other has chosen is a small, intimate, free surprise.",["Go to a library or to the bookshelf at home.","The planner secretly picks a book and a lovely page.","The other reads the page aloud, having never seen it before.","Talk about what you thought and felt.","Swap roles."],"Pick short, gentle texts: the reading flows more lightly.",null,"The planner picks the book and page in secret; the other only reads it on the spot."],
    "V2-283": ["A sunset afternoon, a bench and a flask of tea","A hot drink, a bench and a changing sky make the afternoon rich with slow, good conversation.",["Prepare a flask of tea or coffee and bring two cups.","Pick a bench or low wall with an open view.","Arrive before sunset and sit facing the sky.","Talk about your day, unhurried and screen-free.","When it gets dark, walk home arm in arm."],"Bring a small blanket: benches cool down quickly.",null,null],
    "V2-284": ["A slow bike ride to a viewpoint","Riding slowly side by side gives you time to talk and to see the city from a different angle.",["Choose an easy route, preferably along a bike path or a quiet street.","Bring water and a simple snack.","Ride at conversation pace, with no racing.","Stop at a viewpoint or garden and rest a while.","Ride back calmly, keeping an eye on traffic."],"If one of you has no bike, you can do the same route on foot.",null,null],
    "V2-285": ["An unhurried garden afternoon: naming flowers and trees","Naming what you see, even with made-up names, makes you look with affection and laugh together.",["Choose a garden or park with plenty of green.","Bring a small notebook and a pen.","Each give a made-up name to a flower or tree and explain the choice.","Jot down the names and sketch quickly, without worrying about talent.","Finish on the prettiest bench, reading the list aloud."],"Respect the plants: look and sketch, but don't pick anything.",null,null],
    "V2-286": ["An afternoon of street music and free concerts","Listening to live music, unhurried and ticket-free, makes the afternoon lovelier and gives you free conversation material.",["Look for a square, garden or street where live music usually plays, or a free concert.","Arrive with no expectations and listen, standing or sitting.","Each pick the piece you liked most and say why.","If you feel like it, dance a little, hand in hand.","End with a stroll, humming your favorite."],"If you have spare coins, you can leave a kind gesture for the artist, but there's no obligation.",null,null],
    "V2-287": ["A walk past dream homes: looking from outside and imagining","Imagining where your dreams might live is a playful way to talk about the future with no commitment.",["Choose a lovely neighborhood with houses or buildings you like to look at.","Stroll slowly, taking in the facades.","Each pick a dream home and explain why.","Imagine together what life would be like there: the kitchen, the garden, the balcony.","Photograph your favorites and choose one as the 'couple's dream'."],"Respect residents' privacy: look from a distance and don't get close to the windows.",null,null],
    "V2-288": ["An animal shelter afternoon: volunteering with walks and cuddles","Caring for animals waiting for a home brings you closer and gives the afternoon meaning.",["Find a local animal shelter and arrange the visit first, asking whether they accept volunteers.","Arrive at the agreed time and follow the shelter's rules.","Help with whatever is asked, like walking dogs or cuddling cats.","Talk about the experience on the way home.","Plan to go back on another afternoon."],"Only adopt if you're both ready and have talked it through calmly beforehand.",null,null],
    "V2-289": ["Surprise capsule day: a hidden activity every hour","A day at home with a secret activity each hour never stands still and keeps the curiosity alive.",["The planner writes 6 activities on folded slips of paper, using only what you have at home, like dancing, cooking something simple or reading aloud.","Put the slips in a box or jar.","Every hour, the other person draws a slip and you both do what it says.","In between, leave some free time to rest.","At the end, pick your favourite activity to do again."],"Mix calm and lively activities so the day has a nice rhythm.",null,"The planner writes the activities; the other person only draws one each hour."],
    "V2-290": ["Hotel-at-home day: your partner is the guest","Treating your partner like a guest for a day, with breakfast in bed and little treats, is pure care that costs almost nothing.",["The planner only shares the date and prepares a 'menu' of services: breakfast in bed, music, a foot massage, a movie.","The 'guest' chooses from the menu throughout the day.","Every little touch counts: a neatly folded towel, a note on the pillow, soft lights in the evening.","At lunch and dinner, serve something simple but beautifully presented.","At the end, the guest leaves a heartfelt 'review'."],"Next time, swap roles.",null,"The planner prepares the menu and the treats; the other person just discovers what is waiting."],
    "V2-291": ["Surprise party for two, with an invitation and a secret theme","A party for two, with an invitation and a theme, makes the day feel special without needing anyone else.",["The planner secretly picks a theme, like the 80s, the beach or a black-tie night.","Give your partner a paper invitation with the time and the dress code.","Decorate the living room with whatever you have at home.","Make simple food to match the theme, with music and a toast.","Finish with a dance and a photo together."],"The theme can be silly: what matters is playing along together.",null,"The planner chooses the theme and writes the invitation; the other person simply receives it."],
    "V2-292": ["An afternoon of treats chosen by your partner","When your partner picks the treats, you discover how well you are known and cared for.",["Each of you secretly writes down 3 simple treats for the other, like a cup of tea, a shoulder massage and a song.","Swap the lists.","Enjoy the treats through the afternoon, with no rush.","After each one, the receiver says thank you and shares how it felt.","Close the afternoon with a long hug."],"If a treat does not quite land, the other person can lovingly ask for a swap.",null,"Each person chooses their treats in secret; you only find out when you receive them."],
    "V2-293": ["Secret route afternoon, on foot or by bike","Following a route only your partner knows is a small adventure, with the charm of not knowing where it ends.",["The planner secretly maps out a 3-hour route with 3 lovely stops.","The other person only knows the time and that they should wear comfortable clothes.","Follow the route together, stopping at each place for a snack or a photo.","At each stop, the planner shares a fun fact or a memory.","End at the most beautiful spot along the way."],"Agree beforehand on the pace and on a signal for 'I need a break'.",null,"The planner maps the route in secret; the other person simply follows."],
    "V2-294": ["Outdoor coffee afternoon: your partner picks the 'signal'","Playing with a secret signal turns the afternoon into a game of attention, and the outdoor coffee sets the mood.",["Agree on 3 signals, like a hand on the shoulder, a tap on the nose and a smile.","Each of you secretly chooses where each signal will happen.","Stroll around the neighbourhood and, at every signal, stop for a small loving gesture.","Pick an outdoor cafe or a bench for the main stop.","At the end, each of you guesses which signal your partner liked best."],"Agree beforehand that the signals are always sweet and discreet.",null,"Each person sets up the signals in secret; the other only discovers them along the way."],
    "V2-295": ["Roll-the-dice day: the dice decides every turn","Letting the dice choose is a light way to let go of control and be surprised together.",["The planner prepares a list of 6 free places or activities, numbered 1 to 6.","Bring a die along, or use the one on your phone.","Roll it and do whatever it picks.","Every 2 hours, roll again.","At the end, choose the one you enjoyed most to do again."],"If something comes up that is not possible, just roll again, no guilt.",null,"The planner chooses the 6 options in secret; the dice decides where you go."],
    "V2-296": ["Shops and gardens afternoon with a note-guided route","A note with the plan for the afternoon guides your wander and keeps your partner curious without spoiling the surprise.",["The planner picks 3 places to explore, like a shop, a garden and a bookshop.","Write a note for each one, with a light little task.","Follow the route together and open one note at each place.","At every stop, share what you liked seeing most.","Finish on a bench, with the last note."],"Just look and chat: there is no need to buy anything.",null,"The planner chooses the places and writes the notes; the other person only opens one at each stop."],
    "V2-297": ["Cosy corner afternoon: each of you sets up a corner for the other","Setting up a beautiful little corner for your partner is a loving gesture that transforms both the home and the afternoon.",["Each of you secretly chooses a spot at home to set up for the other: an armchair, a window, a table.","Split the afternoon in two parts: first one of you gets ready, then the other.","Use what you have: blankets, cushions, candles or simple flowers.","When you are done, lead your partner to the corner with their eyes closed.","Spend some time together in each corner, with a cup of tea or some music."],"Skip candles if you have pets or small children; use a soft lamp instead.",null,"Each person sets up their corner in secret; the other only sees it at the end."],
    "V2-298": ["Morning, afternoon and evening notes day","Three notes, one for each part of the day, are enough to give the whole day a thread, without much effort.",["The planner writes 3 notes: one for the morning, one for the afternoon and one for the evening.","Each note holds a free place or a simple activity.","In the morning, open the first one and do it together.","In the afternoon, open the second, and in the evening the third, with a loving finish.","Before bed, share your favourite moment of the day."],"A rest break in the middle makes a big difference.",null,"The planner writes the notes; the other person only opens each one when its time comes."],
  },
};
